(1757, 'INTERFAZ ESTANDAR PARA MEDICION DE IBP DAÑADO CUBICULO 3 UCI 3', 'INTERFAZ ESTANDAR CUBICULO 3 UCI 3', 138, 104, 3, NULL, 11, 4, NULL, NULL, '2022-06-06 12:19:12', NULL, '2022-06-07 09:32:25', 'Se reemplaza cable interfaz por uno nuevo ya que estos son en comodato.\r\nSe le recomienda al personal el cuidado de los accesorios de los monitores', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2022-06-07 00:00:00', '2022-06-06 14:07:58', 11, NULL, 750, '', NULL, 15, NULL, '9277afa7d8dc1d7e3b1e9fda9069a450.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Angelica Maria Campo M', NULL, NULL, '1757', 0, '', '', '', 11, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1758, 'CABLE DE SATURADOR  DAÑADO POR PACIENTE SE PARTIO ', 'CABLE SATURADOR DAÑADO ', 140, 104, 3, NULL, 11, 4, NULL, NULL, '2022-06-06 15:34:14', NULL, '2022-06-16 07:26:11', 'Se realiza cambio de cable de ECG por uno nuevo, el equipo queda funcional', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2022-06-15 00:00:00', '2022-06-07 09:18:25', 11, NULL, 876, '', NULL, 15, NULL, 'a2b4210e16d16aa9b9a491ff8b392928.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Angelica Maria Campo M', NULL, NULL, '1758', 0, '', '', '', 11, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1759, 'Cuando se enciende la unidad odontologica portatil presenta una fuga de aire', 'Unidad odontologica presenta figa de aire', 65, 116, 3, NULL, 116, 4, NULL, NULL, '2022-06-07 09:32:21', NULL, '2022-06-07 11:24:50', 'SE REALIZA PREVIA INSPECCIÓN DE TODO EL SISTEMA DE LA UNIDAD DE ODONTOLOGÍA. SE REALIZA LA APERTURA DE LAS VÁLVULAS DE CORTE DE AIRE Y AGUA. SE EVIDENCIA LA EXISTENCIA DE UNA FUGA DE AIRE. SE REPARA LA MANGUERA CON LA FUGA. SE SE EJECUTAN PRUEBAS DE FUNCIONAMIENTO. EQUIPO FUNCIONA ADECUAMENTE.																																																									\r\n																																																									', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2022-06-07 10:00:00', '2022-06-07 09:36:45', 116, NULL, 994, '', NULL, 15, NULL, 'bd0deeede894472f5a3c35fa38c02a0c.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Alejandro Torres ', NULL, NULL, 'C0066', 0, '', '', '', 116, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
