(2645, 'Reportan del servicio interferencia en el equipo, por lo que se retiro del servicio y debe ser enviado a Jomedical para revisión por garantía', 'Equipo presenta interferencia', 40, 7, 5, NULL, 7, 4, NULL, NULL, '2023-04-03 09:16:54', NULL, '2023-07-19 09:01:33', 'Se entrega equipo en el servicio en optimas condiciones funcionales', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2023-07-18 00:00:00', '2023-04-03 09:17:21', 7, NULL, 3870, '', NULL, 15, NULL, '60f2b8464ce48b34bd2feb9656f9bd87.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Denis Guevara Pinilla', NULL, NULL, '00746', 0, '', '', '', 7, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
