(3290, 'equipo de organos del consultorio 1 no enciende no funciona.', 'equipo de organos no enciende', 71, 90, 3, NULL, 42, 4, NULL, NULL, '2023-09-13 10:06:33', NULL, '2023-09-14 11:18:21', 'SE REVISA EQUIPO, SE EVIDENCIA MALA CONEXION DE LOS CABLES HELICOIDALES EN LOS SENSORES OPTICOS, SE ACOMODAN CORRECTAMNETE, SE REALIZA LA CAPACITACION DEL USO ADECUADO DEL EQUIPO, SE PRUEBAN EL FUNCIONAMIENTO DEL EQUIPO. EQUIPO FUNCIONA CORRECTAMENTE, SE DEJA EN EL SERVICIO EN OPTIMAS CONDICIONES. ', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2023-09-14 11:15:00', '2023-09-13 11:14:39', 42, NULL, 2906, '', NULL, 15, NULL, '24dd1b268f6e3602218305873aa481bb.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, '3290', 0, '', '', '', 42, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3291, 'MONITOR DE SIGNOS SE ENCUENTRA CON MALA CALIBRACIÓN, NO MARCA TENSION ARTERIAL Y SATURACIÓN', 'MONITOR DE SIGNOS VITALES', 144, 118, 3, NULL, 42, 4, NULL, NULL, '2023-09-13 10:35:34', NULL, '2023-09-14 11:23:25', 'SE ATIENDE LLAMADO, SE REVISA EQUIPO, SE EVIDENCIA MAL POSICIONAMEINTO DEL SENSOR SPO2, IMPIDIENDO EL COPRRECTO FUNCIONAMIENTO DEL EQUIPO, SE REALIZA AJUSTE DEL SENSOR, EQUIPOP FUNCIONA CORRECTAMNETE, SE TOMAN PRUEBAS DE FUNCIONAMIENTO DEL BRAZALETE, EQUIPO OPERA CORRECTAMNETE, SE DEJA EN EL SERVICIO EN OPTIMAS CONDICIONES.\r\n', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2023-09-14 11:22:00', '2023-09-13 11:10:43', 42, NULL, 612, '', NULL, 15, NULL, '01abd08ab14e1f7cdfa218f15fa7f894.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, '3291', 31, '', '', '', 42, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
