(3294, 'cable ekg  se encuentra deteriorado por favor revisar ', 'CABLE EKG DAÑADO ', 238, 104, 3, NULL, 42, 4, NULL, NULL, '2023-09-14 09:52:53', NULL, '2023-09-15 15:57:31', 'SE ATIENDE LLAMADO, SE EVIDENCIA ACCESORIO EN MALAS CONDICIONES, SE REALIZA CAMBIO DE ACCESORIO SE TOMAN PRUEBAS DE FUNCIONAMIENTO, EQUIPO FUNCIONA CORRECTAMENTE, SE DEJA EN EL SERVICIO EN OPTIMAS CONDICIONES.\r\n', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2023-09-15 15:56:00', '2023-09-14 16:02:04', 42, NULL, 864, '', NULL, 15, NULL, 'c0de7942d616acfe913410a2401b42f1.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, '3294', 0, '', '', '', 42, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3295, 'termómetro no funciona por favor revisar ', 'TERMOMETRO dañado ', 238, 104, 3, NULL, 42, 4, NULL, NULL, '2023-09-14 09:54:04', NULL, '2023-09-15 15:55:49', 'SE ATIENDE LLAMADO, SE EVIDENCIA ACCESORIO EN MALAS CONDICIONES, SE REALIZA CAMBIO DE ACCESORIO SE TOMAN PRUEBAS DE FUNCIONAMIENTO, EQUIPO FUNCIONA CORRECTAMENTE, SE DEJA EN EL SERVICIO EN OPTIMAS CONDICIONES.\r\n', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2023-09-15 15:54:00', '2023-09-14 15:59:18', 42, NULL, 864, '', NULL, 15, NULL, '106bc5f8de7d0553045d12258a79653e.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, '3295', 0, '', '', '', 42, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3296, 'MONITOR DE SIGNOS VITALES NO INSUFLA, FAVOR REVISAR ', 'MONITOR DE SIGNOS VITALES ', 72, 42, 3, NULL, 42, 4, NULL, NULL, '2023-09-14 11:42:58', NULL, '2023-09-14 11:45:54', 'PREVIA LIMPIEZA Y DESINFECCION DEL EQUIPO, EQUIPO SE ENCUENTRA EN EL TALLER POR DAÑO EN LA BOMBA DE PRESION, SE REALIZA CAMBIO DE BOMBA, SE INSTALA BRAZALETE, SE TOMAN PRUEBAS DE FUNCIONAMIENTO, EQUIPO FUNCIONA CORRECTAMNETE, SE DEJA EN EL SERVICIO EN OPTIMAS CONDICIONES.', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2023-09-14 11:44:00', '2023-09-14 11:45:04', 42, NULL, 801, '', NULL, 15, NULL, 'b3eaaa7eec96121760c1a9e51c26f6b0.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, '3296', 0, '', '', '', 42, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
